import{z as n,x as s,o as B,c as d,q as t,j as i,D as a,d as A,s as o,S as r,b as l}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"多模态 RAG","description":"","frontmatter":{"title":"多模态 RAG","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rag-multimodal.md","filePath":"llm/rag-multimodal.md","lastUpdated":1791063341000}'),C={name:"llm/rag-multimodal.md"};function p(m,E,D,F,c,u){const e=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=t('<h1 id="多模态-rag" tabindex="-1">多模态 RAG <a class="header-anchor" href="#多模态-rag" aria-label="Permalink to &quot;多模态 RAG&quot;">​</a></h1><div class="epigraph"><p>答案住在图里时，caption 是翻译，嵌入是罗盘，页面渲染是原件；翻译会丢数，罗盘找得着但读不了，原件最贵也最忠实。</p><footer>—— Radford 等 CLIP 的双塔口径；Faysse 等 ColPali 的视觉文档检索路线</footer></div><p><a href="/llm/rag-structured-data">上一课</a>把表格与关系库接进路由。语料的另一大类是视觉：扫描件、图表、幻灯片、带版面的 PDF。第一课说过「切分修不了烂抽取」，在多模态这里抽取本身就是问题——两栏排版、表格嵌图、图注分离，解析器输出的常是乱码与孤儿图。本课写视觉对象怎么进索引、怎么被引用：caption 化、跨模态嵌入、页面级视觉检索三条路线的选择与代价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>默认管线把 PDF 拍成纯文本，图表要么丢失要么变成残句；检索根本看不见这些对象，生成器自然也引用不了。三条路线各有代价：caption 化用 VLM 描述图像再把描述当文本索引——图表可被文本查询命中，但描述是「翻译」，精确数值与坐标刻度被概率化；跨模态嵌入用 CLIP 式双塔把图块与文本查询放进同一余弦空间（<a href="/llm/multimodal-embeddings">多模态嵌入</a>的口径）——找得着图，但向量读不了图；页面级视觉检索把整页渲染成图，查询与页面版面块做晚交互匹配（ColPali 路线）——绕过解析整条链，索引与匹配都贵。选择困难在于：答案到底住在哪。</p><p><span class="marginnote">术语翻译：跨模态嵌入就是把图和句子投进同一个「相似度空间」——文字「上涨的红色折线」和含红色折线的图，向量会离得近，所以能用文字搜图。但它只负责「找得像」，图里数字是多少、轴代表什么，向量一概不知道，读图是生成阶段 VLM 的事。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按「答案住在哪」选路线。答案在正文文本，图只是装饰：纯文本管线足够，别为它付视觉税。答案在图表的视觉结构（趋势、形状、布局）：caption 会丢、单向量抓不住，选跨模态或页面级。答案在图文对应（「图 3 那条曲线说明什么」）：引用要能指回页面区域，页面级检索或「caption 化 + 原图锚点」都行，但引用粒度必须是区域不是整页。caption 化管线的工程纪律：让 VLM 输出结构化描述（图表类型、轴、关键数值、结论），数值走校验回环——关键数值 OCR 或回读原图比对，不一致丢弃；描述与原文位置一起索引，引用才能落回原页。图文混排的块定义扩成「文本跨度或页面区域」，第一课的金标跨度协议照用，只是标注对象多了一类。</p><p><span class="marginnote">数字实例：索引体积差距有多大——文本路线一段 500 词只需 1 个向量；页面级视觉检索一页要为版面上的每个块存几十到上千个向量。十万页文档按后者索引，存储与匹配开销直接涨几个数量级，这就是「降维打击烂 PDF」要交的学费，也是按域路由的价值所在。</span></p>',9)),(B(),i(r,null,{default:a(()=>[o(e,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOC%5B%22%E8%A7%86%E8%A7%89%E6%96%87%E6%A1%A3%22%5D%20--%3E%20Q1%7B%22%E7%AD%94%E6%A1%88%E4%BD%8F%E5%9C%A8%E5%93%AA%22%7D%0A%20%20Q1%20--%3E%7C%E6%AD%A3%E6%96%87%E6%96%87%E6%9C%AC%7C%20TXT%5B%22%E7%BA%AF%E6%96%87%E6%9C%AC%E7%AE%A1%E7%BA%BF%22%5D%0A%20%20Q1%20--%3E%7C%E5%9B%BE%E8%A1%A8%E7%BB%93%E6%9E%84%7C%20CAP%5B%22caption%20%E5%8C%96%20%2B%20%E6%95%B0%E5%80%BC%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20Q1%20--%3E%7C%E7%89%88%E9%9D%A2%E4%B8%8E%E5%9B%BE%E6%96%87%E5%AF%B9%E5%BA%94%7C%20PAGE%5B%22%E9%A1%B5%E9%9D%A2%E6%B8%B2%E6%9F%93%20%2B%20%E6%99%9A%E4%BA%A4%E4%BA%92%E5%8C%B9%E9%85%8D%22%5D%0A%20%20CAP%20--%3E%20IDX%5B%22%E6%8F%8F%E8%BF%B0%E4%B8%8E%E4%BD%8D%E7%BD%AE%E4%B8%80%E8%B5%B7%E7%B4%A2%E5%BC%95%22%5D%0A%20%20PAGE%20--%3E%20IDX2%5B%22%E9%A1%B5%E7%BA%A7%E5%A4%9A%E5%90%91%E9%87%8F%E7%B4%A2%E5%BC%95%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=l("h2",{id:"机制",tabindex:"-1"},[A("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=l("p",null,"caption 化为什么有损却常值：VLM 的描述把图接入文本查询的词汇空间，可与文本块融合排序、共享重排；损失在数值——概率化的「约 34%」在下游就是错误引用，所以数值校验回环不是可选项。跨模态嵌入为什么找得着读不了：双塔对齐的是「查询短语与图像区域」的绑定关系，判定相关可以，支撑答案不行，命中后仍需 VLM 读图生成。页面级检索为什么规避了解析：它把「解析–切分–嵌入」整条链换成「渲染–匹配」，对烂 PDF 是降维打击；代价是每页多向量、索引体积涨一个量级、专用匹配器与推理服务。三条路线不是互斥：正文走文本、图表走 caption、版面敏感域走页面级，路由按域与问题类型分，与上一课的意图路由同一套纪律。",-1)),(B(),i(r,null,{default:a(()=>[o(e,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMG%5B%22%E9%A1%B5%E9%9D%A2%E9%87%8C%E7%9A%84%E5%9B%BE%E8%A1%A8%22%5D%20--%3E%20VLM%5B%22VLM%20%E7%94%9F%E6%88%90%E7%BB%93%E6%9E%84%E5%8C%96%E6%8F%8F%E8%BF%B0%3A%20%E7%B1%BB%E5%9E%8B%2F%E8%BD%B4%2F%E6%95%B0%E5%80%BC%2F%E7%BB%93%E8%AE%BA%22%5D%0A%20%20VLM%20--%3E%20CHECK%7B%22%E5%85%B3%E9%94%AE%E6%95%B0%E5%80%BC%E6%A0%A1%E9%AA%8C%E5%9B%9E%E7%8E%AF%3A%EF%BC%9Cbr%2F%EF%BC%9EOCR%20%E6%88%96%E5%9B%9E%E8%AF%BB%E5%8E%9F%E5%9B%BE%E6%AF%94%E5%AF%B9%22%7D%0A%20%20CHECK%20--%20%22%E4%B8%80%E8%87%B4%22%20--%3E%20IDX%5B%22%E6%8F%8F%E8%BF%B0%20%2B%20%E5%8E%9F%E5%9B%BE%E4%BD%8D%E7%BD%AE%E4%B8%80%E8%B5%B7%E7%B4%A2%E5%BC%95%22%5D%0A%20%20CHECK%20--%20%22%E4%B8%8D%E4%B8%80%E8%87%B4%22%20--%3E%20DROP%5B%22%E4%B8%A2%E5%BC%83%E6%8F%8F%E8%BF%B0%2C%20%E9%98%B2%E9%94%99%E8%AF%AF%E5%BC%95%E7%94%A8%22%5D%0A%20%20IDX%20--%3E%20HIT%5B%22%E6%96%87%E6%9C%AC%E6%9F%A5%E8%AF%A2%E5%91%BD%E4%B8%AD%E5%9B%BE%E8%A1%A8%22%5D%0A%20%20HIT%20--%3E%20CITE%5B%22%E5%BC%95%E7%94%A8%E6%8C%87%E5%9B%9E%E5%8E%9F%E9%A1%B5%E5%8C%BA%E5%9F%9F%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">常见误区：初学者容易以为「上了多模态模型就一步到位」。实际上检索与读图是两种能力：嵌入模型决定「找不找得到那张图」，VLM 决定「读得对不对」。检索没命中，再强的 VLM 也无图可读；检索命中了、VLM 读错数，就成了带引用的幻觉——两段要分开评测。</span></p><p><span class="marginnote">图表问答里最常见的静默失败：描述里写「约增长三成」，原图是 41%——判官看描述打分是高分，看原图是错。验收多模态 RAG 必须让评审判官看见原图，而不是只看 caption。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>多模态嵌入与 VLM 早融合是两种系统，检索对绑定、生成对读图，别让一个组件干两件事。图像进索引前过隐私与版权筛，可写索引的注入面在投毒防御课的口径下同样适用，图不是法外之地。视频是多一条时间轴的问题，镜头切分与帧采样另成体系，本课不展开。视觉解析质量低到一定程度，先修 OCR 与版面模型再谈路线——它与文本侧同一条边界：管线修不了上游的烂输入。检索之外，视觉 token 的上下文预算与生成侧服务见多模态推理服务的课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>按答案住址选路线：正文文本、图表结构、版面对应，各走各的管线。</li><li>caption 化有损但接入词汇空间；数值必须校验回环，不然就是错误引用。</li><li>跨模态嵌入管找不管读；命中后读图交给 VLM。</li><li>页面级视觉检索绕过解析链，代价是索引体积与专用服务。</li><li>图文混排的金标跨度扩成「文本跨度或页面区域」，评测判官要看原图。</li><li>出处：Radford 等 CLIP；Faysse 等 ColPali；据多模态检索工程实践整理。</li></ul>',6))])}const f=n(C,[["render",p]]);export{P as __pageData,f as default};
